const brand=`<a class="brand" href="/"><img src="/assets/logo.png" alt="Gulf Seismic logo"><span><strong>Gulf Seismic</strong><small>Seismic • Technical • Road Marking</small></span></a>`;
function header(){return `<header class="header"><div class="container header-inner">${brand}<nav class="nav" aria-label="Main navigation"><a href="/services">Services</a><a href="/uae">UAE</a><a href="/saudi-arabia">Saudi Arabia</a><a href="/projects">Projects</a><a href="/industries">Industries</a><a href="/blog">Blog</a><a href="/about">About</a></nav><div class="header-actions"><a class="call" href="tel:+97125555769">☎ &nbsp; Call</a><a class="btn" href="/contact">Get a Quote</a></div><button class="menu-btn" aria-label="Open menu" aria-expanded="false">☰</button></div><nav class="mobile-nav" aria-label="Mobile navigation"><a href="/services">Services</a><a href="/uae">UAE</a><a href="/saudi-arabia">Saudi Arabia</a><a href="/projects">Projects</a><a href="/industries">Industries</a><a href="/blog">Blog</a><a href="/about">About</a><a href="/contact">Get a Quote</a></nav></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand}<p>Gulf Seismic General Contracting L.L.C. provides road and industrial marking from Abu Dhabi, with service coverage across the UAE and Saudi Arabia.</p></div><div><h4>Services</h4>${services.map(s=>`<a href="${serviceHref(s)}">${s[0]}</a>`).join('')}</div><div><h4>Company</h4>${[['About Us','/about'],['Projects','/projects'],['Industries','/industries'],['Blog','/blog'],['Contact','/contact']].map(x=>`<a href="${x[1]}">${x[0]}</a>`).join('')}</div><div><h4>Get in Touch</h4><a href="tel:+97125555769">+971 2 555 5769</a><a href="mailto:roadmarking@gulfseismic.com">roadmarking@gulfseismic.com</a><p>P.O. Box 93187, Abu Dhabi, United Arab Emirates</p>${btn('Request a Quote','/contact')}</div></div><div class="footer-bottom"><span>© 2026 Gulf Seismic. All rights reserved.</span><span>Serving 16 cities across the Gulf</span></div></div></footer>`}
function sectionHead(kicker,title,description){return `<div class="section-head"><span class="eyebrow">${kicker}</span><h2>${title}</h2><p>${description}</p></div>`}
function serviceCards(){return `<div class="services-grid">${services.map(s=>`<a class="service-card" href="${serviceHref(s)}"><img src="/assets/${s[1]}.jpg" alt="${s[0]}" loading="lazy"><div class="card-body"><h3>${s[0]}</h3><p>${s[2]}</p><span class="learn">Learn more →</span></div></a>`).join('')}</div>`}
function cities(country,items){return `<div class="city-list">${items.map(c=>`<a href="${cityHref(c,country)}">${c}</a>`).join('')}</div>`}
function projectsGrid(limit=projects.length){return `<div class="projects-grid">${projects.slice(0,limit).map((p,i)=>`<a class="project-card" href="/projects/${slug(p[0])}"><span class="kind">Evidence document on file</span><h3>${p[0]}</h3><p>${p[3]}</p><small>🇦🇪 ${p[2]} · ${p[1]}</small><p class="learn" style="margin:18px 0 0">View evidence →</p></a>`).join('')}</div>`}
function industryCards(){return `<div class="industries-grid">${industries.map(i=>`<a href="/industries/${slug(i[0])}" class="industry-card"><div class="icon">${i[2]}</div><h3>${i[0]}</h3><p>${i[1]}</p><span class="learn">Explore industry →</span></a>`).join('')}</div>`}
function quoteSection(){return `<section class="section quote-section" id="quote"><div class="container quote-layout"><div>${sectionHead('Get a Quote','Start your marking project today','Choose the channel that suits you. Contact Gulf Seismic with your drawings, site details and project requirements.')}<div class="contact-tiles"><a href="https://wa.me/971549970833"><strong>WhatsApp ↗</strong>Message our team</a><a href="tel:+97125555769"><strong>Call ↗</strong>+971 2 555 5769</a><a href="mailto:roadmarking@gulfseismic.com"><strong>Email ↗</strong>roadmarking@gulfseismic.com</a><div><strong>Tender ↗</strong>Send an RFQ via form</div></div><h3>Why Gulf Seismic?</h3><ul class="list-check"><li>Scoped quotations from drawings and site conditions</li><li>UAE and Saudi Arabia project coverage</li><li>Evidence-backed project documents where retained</li><li>WhatsApp, phone and email response channels</li></ul></div><form class="quote-form" id="quote-form"><h3>Request a Free Quote</h3><div class="form-grid"><label class="field">Full Name *<input name="name" required placeholder="Ahmed Al Mansoori"></label><label class="field">Company<input name="company" placeholder="Company name"></label><label class="field">Email *<input name="email" type="email" required placeholder="you@company.com"></label><label class="field">Phone / WhatsApp *<input name="phone" required placeholder="+971 50 123 4567"></label><label class="field">Country<select name="country" id="country"><option value="">Select country</option><option>United Arab Emirates</option><option>Saudi Arabia</option></select></label><label class="field">City<select name="city" id="city"><option value="">Select city</option></select></label><label class="field full">Service<select name="service"><option value="">Select service</option>${services.map(s=>`<option>${s[0]}</option>`).join('')}</select></label><label class="field full">Project Details *<textarea name="details" required placeholder="Tell us about your location, scope and timeline"></textarea></label></div><div class="buttons"><button class="btn" type="submit">Prepare Quote Email <span class="arrow">→</span></button></div><div class="form-message" aria-live="polite"></div><p class="form-note">This opens your email app with the request prepared for Gulf Seismic.</p></form></div></section>`}
function cta(){return `<section class="cta"><div class="container"><div><h2>Ready to mark your next project?</h2><p>Talk to a Gulf Seismic specialist about your scope.</p></div>${btn('Request a Quote','/contact','dark')}</div></section>`}
function home(){return `<main><section class="hero"><div class="hero-grid"></div><div class="container"><div class="hero-copy"><div class="hero-badge"><span class="dot"></span> UAE + KSA Coverage | 7+ Years Experience | 15+ Industry Clients</div><h1>Precision. Safety. Quality.</h1><p>Gulf Seismic General Contracting L.L.C. is a leading road marking service provider based in Abu Dhabi, UAE, with operations across Saudi Arabia. We deliver durable, standards-compliant road marking solutions using advanced machinery and premium materials.</p><div class="buttons">${btn('Get a Free Quote','/contact')}${btn('Explore Services','/services','outline')}</div><div class="trust"><span>♧ Spec-led delivery</span><span>☆ Evidence docs on file</span><span>◎ UAE & Saudi Arabia</span></div></div><div class="glance"><div class="glance-title">Gulf Seismic at a Glance <span class="tag">10+ YEARS</span></div><div class="stats"><div class="stat"><strong>2</strong><small>UAE + KSA</small></div><div class="stat"><strong>7+</strong><small>Years Experience</small></div><div class="stat"><strong>12+</strong><small>Services</small></div><div class="stat"><strong>15+</strong><small>Clients</small></div></div></div></div></section><section class="section"><div class="container">${sectionHead('Our Services','Eight specialised marking disciplines','Every service is engineered for Gulf conditions — extreme heat, UV exposure and heavy traffic — and quoted to the project’s applicable specification.')}${serviceCards()}</div></section><section class="section graph"><div class="container graph-layout"><div>${sectionHead('The Authority Graph','One connected platform, dozens of authority nodes','Explore our services, cities, sectors and evidence-backed projects across the Gulf.')}${btn('Explore Services','/services')}</div><div class="graph-flow"><div class="graph-steps"><span>Country</span><span>→ City</span><span>→ Service</span><span>→ Industry</span><span>→ Project</span><span>→ Blog</span></div><div class="graph-numbers"><div><strong>2</strong><small>Countries</small></div><div><strong>16</strong><small>Cities</small></div><div><strong>8</strong><small>Core services</small></div></div></div></div></section><section class="section alt"><div class="container">${sectionHead('Coverage','16 cities. Two nations. One standard.','From Abu Dhabi to Madinah, Gulf Seismic supports road and facility marking projects across the UAE and Saudi Arabia.')}<div class="coverage-grid"><div class="country-card"><h3>🇦🇪 United Arab Emirates</h3><p>8 cities served</p>${cities('uae',uae)}</div><div class="country-card"><h3>🇸🇦 Kingdom of Saudi Arabia</h3><p>8 cities served</p>${cities('saudi-arabia',ksa)}</div></div></div></section><section class="section"><div class="container">${sectionHead('How We Work','A proven five-step delivery process','From survey to handover, each stage is scoped around the site and the approved project specification.')}<div class="process-grid">${[['Consult & Survey','Assess site, specification and traffic conditions.'],['Design & Plan','Select layout, materials and programme.'],['Mobilise','Bring crews and equipment to site.'],['Execute','Apply markings with quality checks.'],['QC & Handover','Verify work and complete handover.']].map((x,i)=>`<div class="process-card"><b>0${i+1}</b><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></div></section><section class="section alt"><div class="container">${sectionHead('Evidence documents on file','Documented projects on file','Public project listings are limited to works backed by retained evidence documents.')} ${projectsGrid(6)}<div class="buttons">${btn('View documented projects','/projects','dark')}</div></div></section><section class="section"><div class="container">${sectionHead('Industries We Serve','Marking expertise for every sector','Each operating environment has distinct safety, durability and wayfinding requirements.')} ${industryCards()}</div></section>${quoteSection()}${cta()}</main>`}
function pageHero(kicker,title,text){return `<section class="page-hero"><div class="container"><div class="crumb"><a href="/">Home</a> / ${kicker}</div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${text}</p></div></section>`}
function about(){return `<main>${pageHero('About Us','Road & industrial marking for Gulf projects','Gulf Seismic General Contracting L.L.C. provides road and facility marking services from Abu Dhabi, UAE, with Saudi Arabia coverage through Seismic Contracting Company LLC.')}<section class="section"><div class="container split"><div><span class="eyebrow">Our story</span><h2>Built for demanding sites</h2><p>Founded in 2018 and headquartered in Abu Dhabi, Gulf Seismic began as a specialist thermoplastic road marking contractor serving the UAE. Today our scope includes highway, parking, warehouse, airport, industrial, safety signage and epoxy flooring work.</p><p>Our delivery approach emphasises clear scope, safe site practice and verification against each client’s approved specification.</p></div><img src="/assets/road-marking.jpg" alt="Road marking work"></div></section><section class="section alt"><div class="container coverage-grid"><div class="country-card"><span class="eyebrow">Our Mission</span><h2>Specification-led delivery</h2><p>To deliver durable road and facility marking for clients across the UAE and Saudi Arabia with clear scope, controlled evidence and responsive quotation support.</p></div><div class="country-card"><span class="eyebrow">Our Vision</span><h2>Trusted execution</h2><p>To be a trusted marking contractor for transport, commercial and industrial clients who need safe execution and accountable follow-through.</p></div></div></section><section class="section"><div class="container">${sectionHead('What We Do','Our core services','Solutions for roads, parking, facilities and industrial environments.')} ${serviceCards()}</div></section>${cta()}</main>`}
function projectsPage(){return `<main>${pageHero('Projects','Evidence-backed marking works','Only projects with a retained evidence document are listed. Contact us for scope details and documentation.')}<section class="section alt"><div class="container">${projectsGrid()}</div></section>${quoteSection()}</main>`}
function projectPage(p){return `<main>${pageHero('Projects',p[0],p[3])}<section class="section"><div class="container narrow"><span class="eyebrow">Documented work</span><h2>Project overview</h2><p>${p[3]}</p><ul class="list-check"><li>Location: ${p[2]}, United Arab Emirates</li><li>Service: ${p[1]}</li><li>Supporting evidence document retained from the previous site</li></ul><p>Request the supporting document and further scope details directly from Gulf Seismic.</p>${btn('Request project details','/contact')}</div></section></main>`}
function industriesPage(){return `<main>${pageHero('Industries','Marking expertise for every sector','From highways to hospitals, each sector has its own marking and safety requirements.')}<section class="section"><div class="container">${industryCards()}</div></section>${quoteSection()}</main>`}
function industryPage(i){return `<main>${pageHero('Industries',i[0],i[1])}<section class="section"><div class="container">${sectionHead('Relevant services','Solutions for this environment','Discuss your site, traffic conditions and required specification with our team.')} ${serviceCards()}</div></section>${cta()}</main>`}
function servicePage(s){return `<main>${pageHero('Service',s[0],s[2])}<section class="section"><div class="container split"><div><span class="eyebrow">Overview</span><h2>${s[0]} for Gulf conditions</h2><p>${s[2]}</p><p>Our team scopes the system, layout, materials and schedule to your drawings, site conditions and the applicable client or authority specification.</p><ul class="list-check"><li>Site survey and specification review</li><li>Material and layout selection</li><li>Controlled application and quality checks</li><li>UAE and Saudi Arabia coverage</li></ul>${btn('Get a Quote','/contact')}</div><img src="/assets/${s[1]}.jpg" alt="${s[0]}"></div></section><section class="section alt"><div class="container">${sectionHead('How We Work','From scope to handover','A consistent delivery process for every marking package.')}<div class="process-grid">${[['Survey','Assess the site and drawings.'],['Plan','Confirm materials and programme.'],['Prepare','Ready the working surface.'],['Apply','Execute to approved layout.'],['Handover','Review completed work.']].map((x,i)=>`<div class="process-card"><b>0${i+1}</b><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></div></section>${quoteSection()}</main>`}
function servicesPage(){return `<main>${pageHero('Services','Road & industrial marking services','Explore our core marking and flooring disciplines for roads, commercial spaces and industrial facilities.')}<section class="section"><div class="container">${serviceCards()}</div></section>${quoteSection()}</main>`}
function countryPage(country){let isUae=country==='uae',list=isUae?uae:ksa,name=isUae?'United Arab Emirates':'Saudi Arabia';return `<main>${pageHero('Coverage',name,`Gulf Seismic serves ${list.length} cities across ${name} with road and industrial marking solutions.`)}<section class="section"><div class="container">${sectionHead('Cities','Explore our coverage','Select a city to see available services and request a quotation.')}<div class="country-card">${cities(country,list)}</div></div></section><section class="section alt"><div class="container">${sectionHead('Services','Marking disciplines','Road, parking, warehouse and industrial marking for your location.')} ${serviceCards()}</div></section>${quoteSection()}</main>`}
function cityPage(city,country){return `<main>${pageHero('Coverage',`Road marking in ${city}`,`Road and industrial marking services for projects in ${city}.`)}<section class="section"><div class="container">${sectionHead('Available services',`Marking solutions in ${city}`,'Speak to our team about drawings, site conditions and specification requirements.')} ${serviceCards()}</div></section>${quoteSection()}</main>`}
function contact(){return `<main>${pageHero('Contact',"Let's talk about your marking project",'Get a free, no-obligation quote from Gulf Seismic specialists.')}<section class="section"><div class="container office-grid"><div class="office-card"><span class="eyebrow">UAE Office (HQ)</span><h3>Abu Dhabi</h3><p>P.O. Box 93187, Abu Dhabi, United Arab Emirates</p><a href="tel:+97125555769">+971 2 555 5769</a><br><a href="tel:+971549970833">+971 54 997 0833</a></div><div class="office-card"><span class="eyebrow">KSA Office</span><h3>Al Khobar</h3><p>Office #405, 4th Floor, Old NCB Bank Building, Cross #18, Prince Thamar Street, King Abdulaziz Road, Al Khobar 31952, Saudi Arabia</p><a href="tel:+966507657243">+966 507 657 243</a></div></div></section>${quoteSection()}</main>`}
const posts=[['Thermoplastic Road Markings UAE','thermoplastic-road-markings-uae','Technical Guide','Thermoplastic is a durable road marking material used for demanding roads in Abu Dhabi and across the UAE.'],['Car Park Surfacing UAE','car-park-surfacing-uae','Commercial','Parking lot pavement repair and route line marking for commercial facilities in Abu Dhabi, UAE.']];
function blog(){return `<main>${pageHero('Blog & Resources','Insights from the Gulf marking industry','Technical guides and project insights from Gulf Seismic across the UAE and Saudi Arabia.')}<section class="section alt"><div class="container"><div class="projects-grid">${posts.map(p=>`<a class="project-card" href="/blog/${p[1]}"><span class="kind">${p[2]}</span><h3>${p[0]}</h3><p>${p[3]}</p><small>Jun 18, 2020</small><p class="learn" style="margin:18px 0 0">Read article →</p></a>`).join('')}</div></div></section></main>`}
function blogPost(p){return `<main>${pageHero('Blog',p[0],p[3])}<section class="section"><div class="container narrow"><span class="eyebrow">${p[2]} · Jun 18, 2020</span><h2>${p[0]}</h2><p>${p[3]}</p><p>Gulf Seismic provides marking solutions for road and facility projects in the UAE. Material selection, site preparation and layout are shaped by the approved project specification and site conditions.</p><p>Speak with our team about a quotation for your project.</p>${btn('Request a Quote','/contact')}</div></section></main>`}
function render(){let path=decodeURI(location.pathname).replace(/\/$/,'')||'/',parts=path.split('/').filter(Boolean),content;if(path==='/')content=home();else if(path==='/about')content=about();else if(path==='/projects')content=projectsPage();else if(path==='/industries')content=industriesPage();else if(path==='/contact')content=contact();else if(path==='/blog')content=blog();else if(path==='/services')content=servicesPage();else if(parts[0]==='services'){const s=services.find(x=>x[1]===parts[1]);content=s?servicePage(s):servicesPage()}else if(parts[0]==='projects'){const p=projects.find(x=>slug(x[0])===parts[1]);content=p?projectPage(p):projectsPage()}else if(parts[0]==='industries'){const i=industries.find(x=>slug(x[0])===parts[1]);content=i?industryPage(i):industriesPage()}else if(parts[0]==='blog'){const p=posts.find(x=>x[1]===parts[1]);content=p?blogPost(p):blog()}else if(parts[0]==='uae'||parts[0]==='saudi-arabia'){const list=parts[0]==='uae'?uae:ksa;const c=list.find(x=>slug(x)===parts[1]||(x==='Al Khobar'&&parts[1]==='khobar'));content=c?cityPage(c,parts[0]):countryPage(parts[0])}else content=home();document.getElementById('app').innerHTML=header()+content+footer();document.title=(path==='/'?'Gulf Seismic':document.querySelector('h1')?.textContent+' | Gulf Seismic')||'Gulf Seismic';document.querySelector('.menu-btn').addEventListener('click',e=>{let n=document.querySelector('.mobile-nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(n.classList.contains('open')))});const country=document.getElementById('country'),city=document.getElementById('city');if(country)country.addEventListener('change',()=>{let opts=country.value==='United Arab Emirates'?uae:country.value==='Saudi Arabia'?ksa:[];city.innerHTML='<option value="">Select city</option>'+opts.map(x=>`<option>${x}</option>`).join('')});let form=document.getElementById('quote-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;let d=new FormData(form),body=[`Name: ${d.get('name')}`,`Company: ${d.get('company')}`,`Email: ${d.get('email')}`,`Phone: ${d.get('phone')}`,`Country: ${d.get('country')}`,`City: ${d.get('city')}`,`Service: ${d.get('service')}`,'',`Project details: ${d.get('details')}`].join('\n');document.querySelector('.form-message').textContent='Your email app will open with the request ready to send.';location.href='mailto:roadmarking@gulfseismic.com?subject='+encodeURIComponent('Gulf Seismic quote request')+'&body='+encodeURIComponent(body)});}
render();
